    final hour = TimeOfDay.now().hour;

    if (hour >= 4 && hour < 12) {
      return '🌤️Good Morning';
    } else if (hour >= 12 && hour < 17) {
      return '☀️Good Afternoon';
    } else if (hour >= 17 && hour < 22) {
