  void _addTimeStampItem(String title) {
    //  a set state will notify the app that the state has changed
    setState(() {
      sundayControllerText.text.length > 0
          ? _timeStampList1.add([title, false])
          : mondayControllerText.text.length > 0
              ? _timeStampList2.add([title, false])
              : tuesdayControllerText.text.length > 0
                  ? _timeStampList3.add([title, false])
                  : wednesdayControllerText.text.length > 0
                      ? _timeStampList4.add([title, false])
                      : thursdayControllerText.text.length > 0
                          ? _timeStampList5.add([title, false])
                          : fridayControllerText.text.length > 0
                              ? _timeStampList6.add([title, false])
                              : saturdayControllerText.text.length > 0
                                  ? _timeStampList7.add([title, false])
                                  : '';
    });

    sundayControllerText.clear();
    mondayControllerText.clear();
    tuesdayControllerText.clear();
    wednesdayControllerText.clear();
    thursdayControllerText.clear();
    fridayControllerText.clear();
    saturdayControllerText.clear();
  }

  void _addTodoJam(String jam) {
    //  a set state will notify the app that the state has changed
    setState(() {
      hour.add(jam);
    });
  }

  Widget _buildTodoJam(String jam) {
    return Column(
      children: [
        Container(
          child: Text(
            'Last Updated' + " " + jam,
            style: TextStyle(
                color: Color.fromARGB(255, 0, 35, 65),
                fontWeight: FontWeight.bold),
          ),
        ),
      ],
    );
  }

  List<Widget> _getJam() {
    final List<Widget> _todoHour = <Widget>[];

    _todoHour.add(_buildTodoJam(jam));

    return _todoHour;
  }

